INSERT INTO help(name_os,Media_os,type_Media_os,category,Description_os) SELECT 'اتصال با v2rayNG در اندروید','','text','اندروید','v2rayNG را از بخش نرم‌افزارها نصب کنید. لینک اشتراک را کپی کنید، در برنامه روی + بزنید، Import config from Clipboard را انتخاب و سپس اتصال را فعال کنید.' WHERE NOT EXISTS(SELECT 1 FROM help WHERE name_os='اتصال با v2rayNG در اندروید');
